tch()\r\n///\r\n@mixin center-stretch($reverse: false, $inline: false) {\r\n  @include row-center-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-end($align: center, $reverse: false, $inline: false) {\r\n  @include row(flex-end, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-end()\r\n///\r\n@mixin end($align: center, $reverse: false, $inline: false) {\r\n  @include row-end($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-end-stretch($reverse: false, $inline: false) {\r\n  @include row-end(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-end-stretch()\r\n///\r\n@mixin end-stretch($reverse: false, $inline: false) {\r\n  @include row-end-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-between($align: center, $reverse: false, $inline: false) {\r\n  @include row(space-between, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-between()\r\n///\r\n@mixin between($align: center, $reverse: false, $inline: false) {\r\n  @include row-between($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-between-stretch($reverse: false, $inline: false) {\r\n  @include row-between(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-between-stretch()\r\n///\r\n@mixin between-stretch($reverse: false, $inline: false) {\r\n  @include row-between-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-around($align: center, $reverse: false, $inline: false) {\r\n  @include row(space-around, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-around()\r\n///\r\n@mixin around($align: center, $reverse: false, $inline: false) {\r\n  @include row-around($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-around-stretch($reverse: false, $inline: false) {\r\n  @include row-around(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-around-stretch()\r\n///\r\n@mixin around-stretch($reverse: false, $inline: false) {\r\n  @include row-around-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-evenly($align: center, $reverse: false, $i