@alias column-around()\r\n///\r\n@mixin col-around($align: center, $reverse: false, $inline: false) {\r\n  @include column-around($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-around-stretch($reverse: false, $inline: false) {\r\n  @include column-around(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-around-stretch()\r\n///\r\n@mixin col-around-stretch($reverse: false, $inline: false) {\r\n  @include column-around-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin column-evenly($align: center, $reverse: false, $inline: false) {\r\n  @include column(space-evenly, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-evenly()\r\n///\r\n@mixin col-evenly($align: center, $reverse: false, $inline: false) {\r\n  @include column-evenly($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-evenly-stretch($reverse: false, $inline: false) {\r\n  @include column-evenly(stretch, $reverse, $inline);\r\n}\r\n","////\r\n/// @group position\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n/// @since 0.1.0\r\n////\r\n\r\n@use 'sass:math';\r\n@use 'sass:meta';\r\n@use 'functions/list';\r\n\r\n///\r\n/// @access private\r\n///\r\n@mixin -inset(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if $top {\r\n    top: $top;\r\n  }\r\n\r\n  @if $right {\r\n    right: $right;\r\n  }\r\n\r\n  @if $bottom {\r\n    bottom: $bottom;\r\n  }\r\n\r\n  @if $left {\r\n    left: $left;\r\n  }\r\n}\r\n\r\n@mixin inset(\r\n  $all: null,\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $t: null,\r\n  $right: null,\r\n  $r: null,\r\n  $bottom: null,\r\n  $b: null,\r\n  $left: null,\r\n  $l: null,\r\n) {\r\n  @include -inset(\r\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\r\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\r\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\r\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\r\n  );\r\n}\r\n\r\n@mixin inset-all($all) {\r\n  @include inset($all: $all);\r\n}\r\n\r\n@mixin inset-none {\r\n  @include inset-all(0);\r\n}\r\n\r\n///\r\n/// @alias inset-none()\r\n///\r\n@mixin inset-0 {\r\n  @include inset-none;\r\n}\r\n\r\n@mixin inset-xy($x: null, $y: null) {\r\n  @include inset($x: $x, $y: $y);\r\n}\r\n\r\n@mixin inset-x($x) {\r\n  @include inset-xy($x: $x);\r\n}\r\n\r\n@mixin inset-x-none {\r\n  @include inset-x(0);\r\n}\r\n\r\n///\r\n/// @alias inset-x-none()\r\n///\r\n@mixin inset-x-0 {\r\n  @include inset-x-none;\r\n}\r\n\r\n@mixin inset-y($y) {\r\n  @include inset-xy($y: $y);\r\n}\r\n\r\n@mixin inset-y-none {\r\n  @include inset-y(0);\r\n}\r\n\r\n///\r\n/// @alias inset-y-none()\r\n///\r\n@mixin inset-y-0 {\r\n  @include inset-y-none;\r\n}\r\n\r\n@mixin top($top) {\r\n  @include inset($top: $top);\r\n}\r\n\r\n@mixin top-none {\r\n  @include top(0);\r\n}\r\n\r\n///\r\n/// @alias top-none()\r\n///\r\n@mixin top-0 {\r\n  @include top-none;\r\n}\r\n\r\n@mixin right($right) {\r\n  @include inset($right: $right);\r\n}\r\n\r\n@mixin right-none {\r\n  @include right(0);\r\n}\r\n\r\n///\r\n/// @alias right-none()\r\n///\r\n@mixin right-0 {\r\n  @include right-none;\r\n}\r\n\r\n@mixin bottom($bottom) {\r\n  @include inset($bottom: $bottom);\r\n}\r\n\r\n@mixin bottom-none {\r\n  @include bottom(0);\r\n}\r\n\r\n///\r\n/// @alias bottom-none()\r\n///\r\n@mixin bottom-0 {\r\n  @include bottom-none;\r\n}\r\n\r\n@mixin left($left) {\r\n  @include inset($left: $left);\r\n}\r\n\r\n@mixin left-none {\r\n  @include left(0);\r\n}\r\n\r\n///\r\n/// @alias left-none()\r\n///\r\n@mixin left-0 {\r\n  @include left-none;\r\n}\r\n\r\n@mixin unset-all {\r\n  @include inset-all(unset);\r\n}\r\n\r\n// translate\r\n\r\n@mixin translate(\r\n  $x: null,\r\n  $y: null,\r\n) {\r\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\r\n    @if $x and $x != 0 and $y and $y != 0 {\r\n      transform: translate($x, $y);\r\n    } @else if $x and $x != 0 {\r\n      transform: translateX($x);\r\n    } @else if $y and $y != 0 {\r\n      transform: translateY($y);\r\n    }\r\n  }\r\n}\r\n\r\n///\r\n/// @access private\r\n///\r\n@mixin -position(\r\n  $position: relative,\r\n  $all: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\r\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\r\n  }\r\n\r\n  position: $position;\r\n  @include inset(\r\n    $all: $all,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $top,\r\n    $right: $right,\r\n    $bottom: $bottom,\r\n    $left: $left,\r\n  );\r\n}\r\n\r\n// relative\r\n\r\n@mixin relative {\r\n  @include -position($position: relative);\r\n}\r\n\r\n///\r\n/// @alias relative()\r\n///\r\n@mixin rel {\r\n  @include relative;\r\n}\r\n\r\n// absolute\r\n\r\n@mixin absolute(\r\n  $all: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @include -position(\r\n    $position: absolute,\r\n    $all: $all,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $top,\r\n    $right: $right,\r\n    $bottom: $bottom,\r\n    $left: $left,\r\n  );\r\n}\r\n\r\n///\r\n/// @alias absolute()\r\n///\r\n@mixin abs(\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $t: null,\r\n  $r: null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include absolute(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin absolute-xy($x: null, $y: null) {\r\n  @include absolute($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias absolute-xy()\r\n///\r\n@mixin absolute-axis($horizontal: null, $vertical: null) {\r\n  @include absolute-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin absolute-all($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n///\r\n/// @alias ab