n  $transitions: ();\r\n\r\n  @for $i from 1 through list.length($props) {\r\n    $prop: list.nth($props, $i);\r\n\r\n    $name: $prop;\r\n    $duration: animations.$transition-duration;\r\n    $function: animations.$transition-function;\r\n\r\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\r\n      $name: list.nth($prop, 1);\r\n\r\n      @if list.nth($prop, 2) {\r\n        $duration: list.nth($prop, 2);\r\n      }\r\n\r\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\r\n        $function: list.nth($prop, 3);\r\n      }\r\n    }\r\n\r\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\r\n  }\r\n\r\n  @if list.length($transitions) > 0 {\r\n    transition: #{list.zip($transitions)};\r\n  }\r\n}\r\n","////\r\n/// @group position\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n/// @since 0.1.0\r\n////\r\n\r\n@use 'sass:math';\r\n@use 'sass:meta';\r\n@use 'functions/list';\r\n\r\n///\r\n/// @access private\r\n///\r\n@mixin -inset(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if $top {\r\n    top: $top;\r\n  }\r\n\r\n  @if $right {\r\n    right: $right;\r\n  }\r\n\r\n  @if $bottom {\r\n    bottom: $bottom;\r\n  }\r\n\r\n  @if $left {\r\n    left: $left;\r\n  }\r\n}\r\n\r\n@mixin inset(\r\n  $all: null,\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $t: null,\r\n  $right: null,\r\n  $r: null,\r\n  $bottom: null,\r\n  $b: null,\r\n  $left: null,\r\n  $l: null,\r\n) {\r\n  @include -inset(\r\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\r\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\r\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\r\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\r\n  );\r\n}\r\n\r\n@mixin inset-all($all) {\r\n  @include inset($all: $all);\r\n}\r\n\r\n@mixin inset-none {\r\n  @include inset-all(0);\r\n}\r\n\r\n///\r\n/// @alias inset-none()\r\n///\r\n@mixin inset-0 {\r\n  @include inset-none;\r\n}\r\n\r\n@mixin inset-xy($x: null, $y: null) {\r\n  @include inset($x: $x, $y: $y);\r\n}\r\n\r\n@mixin inset-x($x) {\r\n  @include inset-xy($x: $x);\r\n}\r\n\r\n@mixin inset-x-none {\r\n  @include inset-x(0);\r\n}\r\n\r\n///\r\n/// @alias inset-x-none()\r\n///\r\n@mixin inset-x-0 {\r\n  @include inset-x-none;\r\n}\r\n\r\n@mixin inset-y($y) {\r\n  @include inset-xy($y: $y);\r\n}\r\n\r\n@mixin inset-y-none {\r\n  @include inset-y(0);\r\n}\r\n\r\n///\r\n/// @alias inset-y-none()\r\n///\r\n@mixin inset-y-0 {\r\n  @include inset-y-none;\r\n}\r\n\r\n@mixin top($top) {\r\n  @include inset($top: $top);\r\n}\r\n\r\n@mixin top-none {\r\n  @include top(0);\r\n}\r\n\r\n///\r\n/// @alias top-none()\r\n///\r\n@mixin top-0 {\r\n  @include top-none;\r\n}\r\n\r\n@mixin right($right) {\r\n  @include inset($right: $right);\r\n}\r\n\r\n@mixin right-none {\r\n  @include right(0);\r\n}\r\n\r\n///\r\n/// @alias right-none()\r\n///\r\n@mixin right-0 {\r\n  @include right-none;\r\n}\r\n\r\n@mixin bottom($bottom) {\r\n  @include inset($bottom: $bottom);\r\n}\r\n\r\n@mixin bottom-none {\r\n  @include bottom(0);\r\n}\r\n\r\n///\r\n/// @alias bottom-none()\r\n///\r\n@mixin bottom-0 {\r\n  @include bottom-none;\r\n}\r\n\r\n@mixin left($left) {\r\n  @include inset($left: $left);\r\n}\r\n\r\n@mixin left-none {\r\n  @include left(0);\r\n}\r\n\r\n///\r\n/// @alias left-none()\r\n///\r\n@mixin left-0 {\r\n  @include left-none;\r\n}\r\n\r\n@mixin unset-all {\r\n  @include inset-all(unset);\r\n}\r\n\r\n// translate\r\n\r\n@mixin translate(\r\n  $x: null,\r\n  $y: null,\r\n) {\r\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\r\n    @if $x and $x != 0 and $y and $y != 0 {\r\n      transform: translate($x, $y);\r\n    } @else if $x and $x != 0 {\r\n      transform: translateX($x);\r\n    } @else if $y and $y != 0 {\r\n      transform: translateY($y);\r\n    }\r\n  }\r\n}\r\n\r\n///\r\n/// @access private\r\n///\r\n@mixin -position(\r\n  $position: relative,\r\n  $all: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\r\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\r\n  }\r\n\r\n  position: $position;\r\n  @include inset(\r\n    $all: $all,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $top,\r\n    $right: $right,\r\n    $bottom: $bottom,\r\n    $left: $left,\r\n  );\r\n}\r\n\r\n// relative\r\n\r\n@mixin relative {\r\n  @include -position($position: relative);\r\n}\r\n\r\n///\r\n/// @alias relative()\r\n///\r\n@mixin rel {\r\n  @include relative;\r\n}\r\n\r\n// absolute\r\n\r\n@mixin absolute(\r\n  $all: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @include -position(\r\n    $position: absolute,\r\n    $all: $all,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $top,\r\n    $right: $right,\r\n    $bottom: $bottom,\r\n    $left: $left,\r\n  );\r\n}\r\n\r\n///\r\n/// @alias absolute()\r\n///\r\n@mixin abs(\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $t: null,\r\n  $r: null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include absolute(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin absolute-xy($x: null, $y: null) {\r\n  @include absolute($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias absolute-xy()\r\n///\r\n@mixin absolute-axis($horizontal: null, $vertical: null) {\r\n  @include absolute-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin absolute-all($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n///\r\n/// @alias absolute-all()\r\n///\r\n@mixin absolute-square($margin) {\r\n  @include absolute-all($margin);\r\n}\r\n\r\n@mixin absolute-fill {\r\n  @include absolute-all(0);\r\n}\r\n\r\n///\r\n/// @alias absolute-fill()\r\n///\r\n@mixin abs-fill {\r\n  @include absolute-fill;\r\n}\r\n\r\n@mixin absolute-0 {\r\n  @include absolute-fill;\r\n}\r\n\r\n///\r\n/// @alias absolute-0()\r\n///\r\n@mixin abs-0 {\r\n  @include absolute-0;\r\n}\r\n\r\n@mixin absolute-xy($x: null, $y: null) {\r\n  @include absolute($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias absolute-xy()\r\n///\r\n@mixin abs-xy($x: null, $y: null) {\r\n  @include absolute-xy($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias absolute-xy()\r\n///\r\n@mixin absolute-axis($vertical: null, $horizontal: null) {\r\n  @include absolute-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin absolute-x($x) {\r\n  @include absolute-xy($x: $x);\r\n}\r\n\r\n///\r\n/// @alias absolute-x()\r\n///\r\n@mixin abs-x($x) {\r\n  @include absolute-x($x);\r\n}\r\n\r\n@mixin absolute-y($y) {\r\n  @include absolute-xy($y: $y);\r\n}\r\n\r\n///\r\n/// @alias absolute-y()\r\n///\r\n@mixin abs-y($y) {\r\n  @include absolute-y($y);\r\n}\r\n\r\n@mixin absolute-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  $translate-x: if($x, -$x, null);\r\n  $translate-y: if($y, -$y, null);\r\n\r\n  @if $translate-x and math.unit($translate-x) != '%' { // e.g., px\r\n    $translate-x: 0;\r\n  }\r\n\r\n  @if $translate-y and math.unit($translate-y) != '%' {\r\n    $translate-y: 0;\r\n  }\r\n\r\n  @include absolute(\r\n    $top: if($y-prop == top, $y, null),\r\n    $right: if($x-prop == right, $x, null),\r\n    $bottom: if($y-prop == bottom, $y, null),\r\n    $left: if($x-prop == left, $x, null),\r\n  );\r\n\r\n  @include translate($x: $translate-x, $y: $translate-y);\r\n}\r\n\r\n///\r\n/// @alias absolute-center()\r\n///\r\n@mixin abs-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  @include absolute-anchor($x: $x, $y: $y, $x-prop: $x-prop, $y-prop: $y-prop);\r\n}\r\n\r\n@mixin absolute-center($x-prop: left, $y-prop: top) {\r\n  @include absolute-anchor($x: 5